function exitWithHelp(programName) {
  process.stdout.write(buildHelp(programName));
  process.exit(0);
}

function exitWithError(programName, message) {
  process.stderr.write(buildUsage(programName));
  process.stderr.write(`${programName}: error: ${message}\n`);
  process.exit(2);
}

function tokenLooksLikeOption(token) {
  return token.length > 1 && token[0] === '-';
}

export function parseArguments(argv) {
  const programName = getProgramName(argv);
  const extras = [];
  let value = '';
  let hasValue = false;

  for (let index = 2; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      exitWithHelp(programName);
    }

    if (token === '--a') {
      index += 1;

      if (index >= argv.length) {
        exitWithError(programName, 'argument --a: expected one argument');
